def compute(vars):
    balance_2008 = vars["v1"]
    maturities_2009 = vars["v2"]
    value = balance_2008 - maturities_2009
    return {
        "value": value,
        "trace": {
            "balance_2008": balance_2008,
            "maturities_2009": maturities_2009,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
